'use strict';
/**
 * FE mock server data contributor for the entity set ProcessTeam (draft root: process team with members and roles).
 * Behavior in mock-backend/services/ProcessService.js; initial data: ProcessTeam.json (generated by the seed).
 */
const processService = require('../../../../mock-backend/services/ProcessService');
const traceability = require('../../../../mock-backend/services/TraceabilityService');
const { run } = require('../../../../mock-backend/services/mockServerAdapter');

module.exports = {
    async onBeforeAddEntry(keys, data) {
        Object.assign(data, processService.initialProcessTeam(data));
    },

    /** Prepare (Save, step 1): name, known users, roles, at least one process owner */
    async onDraftPrepare(actionDefinition, responseData, keys, odataRequest) {
        await run(this, odataRequest, (repo) => processService.validateProcessTeam(repo, keys.ProcessTeam), { boundAction: true });
    },

    /** Activate: value helps (teams, members) and the read models (roles count for approval and execution) */
    async onAfterAction(actionDefinition, actionData, keys, responseData, odataRequest) {
        const response = await responseData;
        if (actionDefinition.name === 'Activate' && keys?.ProcessTeam) {
            await run(this, odataRequest, async (repo) => {
                await processService.syncTeamValueHelps(repo, keys.ProcessTeam);
                await traceability.refreshAll(repo);
            });
        }
        return response;
    }
};
